import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/APPLY-DICTIONARY.md","filePath":"manual-en/APPLY-DICTIONARY.md","lastUpdated":1785684581000}'),l={name:"manual-en/APPLY-DICTIONARY.md"};function r(n,e,o,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h3 id="_9-1-apply-dictionary" tabindex="-1">9.1 APPLY DICTIONARY <a class="header-anchor" href="#_9-1-apply-dictionary" aria-label="Permalink to &quot;9.1 APPLY DICTIONARY&quot;">​</a></h3><pre><code>APPLY DICTIONARY FROM={’file_name’,file_handle}.
</code></pre><p><code>APPLY DICTIONARY</code> applies the variable labels, value labels, and missing values taken from a file to corresponding variables in the active dataset. In some cases it also updates the weighting variable.</p><p>The <code>FROM</code> clause is mandatory. Use it to specify a system file or portable file’s name in single quotes, a data set name (see <a href="./Datasets">Datasets</a>), or a file handle name (see <a href="./File-Handles">File Handles</a>). The dictionary in the file is be read, but it does not replace the active dataset’s dictionary. The file’s data is not read.</p><p>Only variables with names that exist in both the active dataset and the system file are considered. Variables with the same name but different types (numeric, string) cause an error message. Otherwise, the system file variables’ attributes replace those in their matching active dataset variables:</p><ul><li>If a system file variable has a variable label, then it replaces the variable label of the active dataset variable. If the system file variable does not have a variable label, then the active dataset variable’s variable label, if any, is retained.</li><li>If the system file variable has custom attributes (see <a href="./VARIABLE-ATTRIBUTE">VARIABLE ATTRIBUTE</a>), then those attributes replace the active dataset variable’s custom attributes. If the system file variable does not have custom attributes, then the active dataset variable’s custom attributes, if any, is retained.</li><li>If the active dataset variable is numeric or short string, then value labels and missing values, if any, are copied to the active dataset variable. If the system file variable does not have value labels or missing values, then those in the active dataset variable, if any, are not disturbed.</li></ul><p>In addition to properties of variables, some properties of the active file dictionary as a whole are updated:</p><ul><li>If the system file has custom attributes (see <a href="./DATAFILE-ATTRIBUTE">DATAFILE ATTRIBUTE</a>), then those attributes replace the active dataset variable’s custom attributes.</li><li>If the active dataset has a weighting variable (see <a href="./WEIGHT">WEIGHT</a>), and the system file does not, or if the weighting variable in the system file does not exist in the active dataset, then the active dataset weighting variable, if any, is retained. Otherwise, the weighting variable in the system file becomes the active dataset weighting variable.</li></ul><p><code>APPLY DICTIONARY</code> takes effect immediately. It does not read the active dataset. The system file is not modified.</p>`,9)])])}const b=a(l,[["render",r]]);export{v as __pageData,b as default};
